update public.video_studio_projects
set style='일반 마피아 비교형 소개 + 진행자 얼굴 + 설명 일러스트',target_duration=200,updated_at=now()
where title='시계탑에 흐른 피';

with copy(position,title,scene_type,start_seconds,end_seconds,script,image_prompt,edit_note,is_short,short_title) as (values
 (0,'일반 마피아로 돌아갈 수 없는 이유','진행자 실사',0,20,'저는 마피아 게임을 정말 좋아합니다. 그런데 이제는 일반 마피아 게임으로 돌아갈 수 없는 몸이 돼버렸습니다. 왜냐고요? 전 세계적으로 사랑받는 마피아 계열 게임, ‘시계탑에 흐른 피’를 해버렸거든요.','진행자 정면 촬영, 첫 문장은 얼굴을 크게 보여 주고 핵심 문구를 큰 자막으로 표시','얼굴 유지 · 첫 5초 큰 자막: 일반 마피아로 돌아갈 수 없는 이유',true,'일반 마피아로 돌아갈 수 없는 이유'),
 (1,'일반 마피아의 아쉬움','진행자 실사',20,52,'일반 마피아 게임에서는 마피아나 경찰, 의사가 아닌 평범한 시민이 걸리면 할 수 있는 일이 상대적으로 적습니다. 특별한 정보나 능력이 없기 때문에 대화만으로 마피아를 찾아야 하죠. 게다가 초반에 죽으면 말도 할 수 없습니다. 남은 시간 동안 다른 사람들이 플레이하는 모습을 지켜봐야 하죠.','일반 시민 역할을 상징하는 인물과 사망 후 관전만 하는 상황을 설명하는 독자적인 일러스트','얼굴 중심 · 평범한 시민과 사망 관전 설명에서 그림 삽입',true,'시민이면 할 일이 없다?'),
 (2,'시계탑은 모두가 능력자','자료 화면',52,88,'하지만 시계탑에 흐른 피는 다릅니다. 모든 플레이어가 서로 다른 캐릭터를 맡고, 각자 고유한 능력을 가집니다. 누구는 게임이 시작될 때 정보를 얻고, 누구는 매일 밤 능력을 사용하며, 누구는 특정한 상황에서 강력한 효과를 발휘합니다. 즉, 평범한 시민이 없습니다. 내가 얻은 정보와 다른 사람의 말을 비교하면서, 마을 사람들 사이에 숨어 있는 악마를 찾아야 합니다.','서로 다른 능력을 가진 캐릭터를 표현한 독자적 인포그래픽과 공식 게임 구성물 자료 화면','‘다릅니다’까지 얼굴 · 이후 캐릭터와 능력 설명 그림 · 마지막 문장에 얼굴 복귀',true,'평범한 시민이 없는 마피아 게임'),
 (3,'죽어도 끝나지 않는다','자료 화면',88,120,'그렇다면 시계탑에서도 죽으면 게임이 끝날까요? 아닙니다. 사망하면 대부분 자신의 능력은 사라지지만, 계속 대화하고 추리하며 게임에 참여할 수 있습니다. 그리고 게임이 끝날 때까지 사용할 수 있는 마지막 투표 한 표도 남습니다. 이 한 표가 마지막 순간에 게임의 승패를 바꿀 수도 있습니다.','사망 표시가 놓인 마을 광장 보드와 마지막 투표 토큰 한 개를 강조하는 설명 화면','질문과 ‘아닙니다’는 얼굴 · 사망 표시와 마지막 투표 설명은 그림 · 끝에 얼굴 복귀',true,'죽어도 마지막 한 표가 남는다'),
 (4,'사회자가 아닌 이야기꾼','자료 화면',120,158,'그리고 시계탑에는 일반적인 사회자 대신 ‘이야기꾼’이 존재합니다. 이야기꾼은 단순히 게임 순서만 진행하는 사람이 아닙니다. 밤에 플레이어를 깨워 능력을 처리하고 정보를 전달하며, 규칙과 캐릭터 능력 안에서 여러 상황을 판단합니다. 특히 취하거나 중독된 플레이어가 어떤 정보를 받는지, 여러 결과 중 어떤 상황이 벌어지는지에 따라 게임의 이야기가 달라질 수 있습니다. 그래서 같은 캐릭터 구성으로 다시 플레이해도 매번 새로운 이야기가 만들어집니다. 이야기꾼이 어떻게 게임을 운영하느냐에 따라서도 재미가 크게 달라지죠.','이야기꾼의 마도서, 밤 순서표, 캐릭터 토큰, 취함과 중독 알림 토큰을 설명하는 자료 화면','‘이야기꾼’까지 얼굴 · 마도서와 밤 진행 그림 · 마지막 두 문장에 얼굴 복귀',false,null),
 (5,'시계탑의 매력 정리','진행자 실사',158,176,'죽어도 끝나지 않고, 모든 플레이어에게 특별한 능력이 있으며, 이야기꾼과 함께 매번 새로운 이야기를 만들어가는 마피아 게임. ‘시계탑에 흐른 피’, 보드라운지에서 직접 경험해 보세요.','진행자 얼굴과 보드라운지 게임 테이블, 시계탑에 흐른 피 구성물을 함께 보여 주는 엔딩 화면','얼굴 중심 · 게임 제목과 보드라운지 방문 문구 자막',true,'죽어도 끝나지 않는 마피아 게임'),
 (6,'다음 영상 예고','진행자 실사',176,200,'다음 영상에서는 실제 게임이 낮과 밤에 어떻게 진행되는지 알려드리고, 각 캐릭터의 능력과 재미있는 활용법도 하나씩 소개하겠습니다. 시계탑의 더 깊은 이야기가 궁금하다면 다음 영상도 놓치지 마세요. 게임 진행 방법과 캐릭터 소개 영상으로 다시 돌아오겠습니다.','다음 영상 예고 카드, 게임 진행 방법과 캐릭터 능력 소개 문구, 보드라운지 로고 공간','끝까지 얼굴 · 마지막에 다음 영상 예고 카드 삽입',false,null)
)
update public.video_studio_scenes scene set
 title=copy.title,scene_type=copy.scene_type,start_seconds=copy.start_seconds,end_seconds=copy.end_seconds,
 script=copy.script,narration=false,image_prompt=copy.image_prompt,edit_note=copy.edit_note,
 is_short=copy.is_short,short_title=copy.short_title,updated_at=now()
from copy join public.video_studio_projects project on project.title='시계탑에 흐른 피'
where scene.project_id=project.id and scene.position=copy.position;

delete from public.video_studio_scenes scene using public.video_studio_projects project
where scene.project_id=project.id and project.title='시계탑에 흐른 피' and scene.position>=7;
